#!/usr/bin/env python3
"""Score-level batch random effects; no claim of causal noise identification."""
from pathlib import Path
import sys,json,time
import numpy as np,pandas as pd
from scipy import linalg,optimize
P=Path(__file__).resolve().parents[2];O=P/'outputs/round4';W=P/'work/round4';A=P/'outputs/round2_A1';sys.path.insert(0,str(A));from compute_reliability import lodo,icc_sem,pair_array,reliability
def fit_reml(g,y):
 age=g.age.to_numpy(float);X=np.c_[np.ones(len(g)),(age-age.mean())/age.std()];dn=g.donor.to_numpy();bn=g.batch.to_numpy();K=np.array([(dn[:,None]==dn[None,:]).astype(float),(bn[:,None]==bn[None,:]).astype(float),np.eye(len(g))]);known=g.cell_sampling_var.to_numpy()+g.algorithm_var.to_numpy();scale=np.var(y,ddof=1);yn=(y-y.mean())/np.sqrt(scale);kn=known/scale
 def obj(v,ret=False):
  V=np.einsum('i,ijk->jk',v,K)+np.diag(kn+1e-10)
  try:
   ch=linalg.cho_factor(V,lower=True,check_finite=False);iy=linalg.cho_solve(ch,yn,check_finite=False);ix=linalg.cho_solve(ch,X,check_finite=False);S=X.T@ix;cs=linalg.cho_factor(S,lower=True,check_finite=False);beta=linalg.cho_solve(cs,X.T@iy,check_finite=False);res=yn-X@beta;alpha=linalg.cho_solve(ch,res,check_finite=False);val=2*np.log(np.diag(ch[0])).sum()+2*np.log(np.diag(cs[0])).sum()+res@alpha
   return (val,beta,alpha) if ret else val
  except linalg.LinAlgError:return 1e100
 fits=[optimize.minimize(obj,s,method='L-BFGS-B',bounds=[(0,None)]*3,options={'maxiter':400,'ftol':1e-11}) for s in [[.4,.1,.4],[.1,.6,.2]]];fit=min(fits,key=lambda z:z.fun);assert fit.success,fit.message;vv=fit.x*scale;V=np.einsum('i,ijk->jk',vv,K)+np.diag(known+scale*1e-10);ch=linalg.cho_factor(V,lower=True,check_finite=False);iy=linalg.cho_solve(ch,y,check_finite=False);ix=linalg.cho_solve(ch,X,check_finite=False);beta=np.linalg.solve(X.T@ix,X.T@iy);alpha=linalg.cho_solve(ch,y-X@beta,check_finite=False);inside=vv[1]*(K[1]@alpha);cross=np.zeros(len(g));coverage=np.zeros(len(g),int)
 for d in sorted(set(dn)):
  te=dn==d;tr=~te;ct=linalg.cho_factor(V[np.ix_(tr,tr)],lower=True,check_finite=False);xt=X[tr];yt=y[tr];iy=linalg.cho_solve(ct,yt,check_finite=False);ix=linalg.cho_solve(ct,xt,check_finite=False);beta=np.linalg.solve(xt.T@ix,xt.T@iy);al=linalg.cho_solve(ct,yt-xt@beta,check_finite=False);kb=K[1][np.ix_(te,tr)];cross[te]=vv[1]*(kb@al);coverage[te]=np.array([len(set(dn[tr][bn[tr]==b])) for b in bn[te]])
 total=vv.sum()+known.mean();non=vv[1]+vv[2]+known.mean();info={'celltype':g.celltype.iloc[0],'n_donors':g.donor.nunique(),'n_visits':len(g),'n_batches':g.batch.nunique(),'REML_converged':bool(fit.success),'donor_variance':vv[0],'batch_variance':vv[1],'visit_plus_residual_variance':vv[2],'known_cell_sampling_variance':g.cell_sampling_var.mean(),'known_pseudocell_variance':g.algorithm_var.mean(),'batch_fraction_total':vv[1]/total,'batch_fraction_non_donor_variance':vv[1]/non,'cell_plus_pseudocell_fraction_non_donor':known.mean()/non,'visits_batch_seen_in_other_donors':int((coverage>0).sum()),'visits_without_external_batch_support':int((coverage==0).sum()),'interpretation':'Conditional score-level crossed donor/batch model with fixed age; batch-associated is not necessarily technical/causal, and visit biological/technical residual remain inseparable.'};return cross,inside,coverage,info
def main():
 assert (O/'round4_execution_contract.json').exists();data=pd.read_csv(A/'main_predictions_with_LODO.csv');pairs=pd.read_csv(O/'T_pair_batch_ledger.csv');strata=[]
 for (clock,ct),g in data.groupby(['clock','celltype']):
  for st in ['7-9d','75-105d','330-400d']:
   for rel in ['same_batch','cross_batch']:
    q,a=pair_array(g,g.age_adjusted.to_numpy(),pairs[pairs.stratum.eq(st)&pairs.batch_relation.eq(rel)]);val=icc_sem(a)[0] if len(a)>=3 else np.nan;strata.append({'clock':clock,'celltype':ct,'stratum':st,'batch_relation':rel,'metric':'LODO_age_acceleration' if clock=='sc-ImmuAging' else 'LODO_age_adjusted_RAM','n_pairs':len(a),'ICC2_1':val,'status':'NOT_ESTIMABLE_N_LT3' if len(a)<3 else 'SMALL_N_LT10' if len(a)<10 else 'ESTIMABLE','interpretation':'Subsets of the same full68 LODO residuals; not randomized batch assignment; same-batch pairs cancel a constant additive batch effect only.'})
 pd.DataFrame(strata).to_csv(O/'Figure2_same_cross_batch_ICC.csv',index=False);rows=[];fits=[];preds=[];contr=[]
 for ct,g in data[data.clock.eq('sc-ImmuAging')].groupby('celltype'):
  g=g.sort_values(['donor','gsm']).reset_index(drop=True);y=g.prediction.to_numpy();cross,inside,coverage,info=fit_reml(g,y);fits.append(info);z=g.copy();z['prediction_unadjusted']=y;z['batch_BLUP_other_donors']=cross;z['batch_BLUP_in_sample_supplementary']=inside;z['other_donors_in_batch']=coverage;z['prediction']=y-cross;z['batch_adjusted_age_acceleration']=lodo(z,z.prediction.to_numpy());preds.append(z);rr,_=reliability(z,pairs,'sc-ImmuAging_crossdonor_batch_adjusted',ct,B=2000)
  for q in rr:q['adjustment']='batch BLUP estimated from other donors, fixed full68 REML variance parameters';q['CI_scope']='conditional on batch correction/variance parameters; LODO refit each donor bootstrap';rows.append(q)
  for st,pp in pairs.groupby('stratum'):
   q,aa=pair_array(g,g.age_adjusted.to_numpy(),pp);_,bb=pair_array(z,z.batch_adjusted_age_acceleration.to_numpy(),pp);before=icc_sem(aa);after=icc_sem(bb);crossshare=pp.batch_relation.eq('cross_batch').mean();mse=np.mean(np.square(aa[:,1]-aa[:,0]));expected=2*info['batch_variance']*crossshare;contr.append({'celltype':ct,'stratum':st,'n_pairs':len(q),'ICC_before':before[0],'ICC_batch_adjusted':after[0],'ICC_change':after[0]-before[0],'SEM_before':before[1],'SEM_batch_adjusted':after[1],'MDC95_before':before[2],'MDC95_batch_adjusted':after[2],'cross_batch_pair_fraction':crossshare,'model_batch_fraction_total':info['batch_fraction_total'],'model_batch_fraction_non_donor_variance':info['batch_fraction_non_donor_variance'],'model_expected_batch_pair_difference_variance':expected,'observed_residual_pair_difference_MSE':mse,'model_expected_batch_over_observed_pair_MSE':expected/mse if mse>0 else np.nan,'interpretation':'Model-dependent batch-associated contribution, not causal technical fraction. May exceed1 when pooled variance does not match interval-specific variance; never clipped.'})
  pd.DataFrame(rows).to_csv(O/'Figure3_batch_adjusted_reliability.csv',index=False);pd.DataFrame(fits).to_csv(O/'T_REML_batch_components.csv',index=False);print('T_BATCH_COMPLETE',ct,info['batch_fraction_non_donor_variance'],flush=True)
 pd.concat(preds,ignore_index=True).to_csv(O/'T_batch_adjusted_predictions.csv',index=False);pd.DataFrame(contr).to_csv(O/'T_batch_contribution_by_type_interval.csv',index=False);(O/'T_status.json').write_text(json.dumps({'status':'PASS','same_batch_pairs':{'7-9d':18,'75-105d':5,'330-400d':0},'cross_batch_pairs':{'7-9d':15,'75-105d':23,'330-400d':62},'batch_dominant31_all_RAM':True,'variance_rows_not_interval_specific':True,'batch_adjustment':'Score-level random effects, not RNA ComBat-seq; retains visit residuals and uses other-donor BLUP','causal_biological_technical_decomposition_identified':False,'adjusted_CI_scope':'Conditional on fitted batch correction; does not propagate its estimation uncertainty'},indent=2));print('T_COMPLETE',flush=True)
if __name__=='__main__':main()
